reasons={
 'fixed-admission-and-bounded-execution':{'reason':'Retain descriptor/metadata/resource admission, envelope and entropy validation, cancellation/deadline checkpoints, asynchronous execution and owning-storage publication. The small absolute fixed cost dominates 361-pixel work. Tiny decode probes localise costs to validated parsing, guarded native decode and the public boundary; tiny RGB encoder and larger context controls corroborate the required execution/storage overhead. No safety guard is disabled.','evidence':['../attribution/tiny-decode-qualified-1.jsonl','../attribution/tiny-decode-qualified-2.jsonl','../attribution/rgb-encode-attribution-1.jsonl','../attribution/rgb-encode-attribution-2.jsonl'],'sourcePaths':['Sources/SwiftJLI/CodecAPI.swift','Sources/SwiftJLI/JPEGCodec.swift','Sources/SwiftJLI/JPEGEnvelope.swift','Sources/SwiftJLI/NativeExecution.swift']},
 'checked-uint12-borrowed-input':{'reason':'Retain fused little-endian/strided UInt12 loading with meaningful-precision validation and per-row cancellation into the required Float algorithm plane. Private native/context/shared/public controls localise the cost to bounded context and checked borrowed reads; public versus shared costs are small. Noise/mixed cases run the same loader as flat/ramp. The roughly pixel-proportional added cost is accepted to preserve correct sample interpretation and zero full-image handoff copies.','evidence':['../attribution/dct12-final-attribution-1.jsonl','../attribution/dct12-final-attribution-2.jsonl'],'sourcePaths':['Sources/SwiftJLI/Native/Contract/SharedDCTStorage.swift','Sources/SwiftJLI/NativeExecution.swift']},
 'bounded-rgb-row-conversion':{'reason':'Retain checked borrowed RGB reads and eight-row conversion scratch with joined, bounded workers and cancellation. Native/context/shared/public encoder controls localise the cost to bounded execution and row conversion; sequential and progressive encoders share this source-conversion path. The measured cost is accepted in exchange for bounded scratch and direct scoped source reads, rather than materialising a full packed source image.','evidence':['../attribution/rgb-encode-attribution-1.jsonl','../attribution/rgb-encode-attribution-2.jsonl'],'sourcePaths':['Sources/SwiftJLI/Native/Contract/SharedRGBInput.swift','Sources/SwiftJLI/NativeExecution.swift']}}
accepted=[]
for row in rows:
 item=dict(row)
 if row['investigationRequired']:
  group='fixed-admission-and-bounded-execution' if row['size']==19 else 'checked-uint12-borrowed-input' if row['profile']=='dct12' else 'bounded-rgb-row-conversion'
  if row['size']>19:assert row['operation']=='Encode'
